alter table public.notes enable row level security;

create policy "R1 R2: authenticated users can read own notes or public notes"
  on public.notes
  for select
  to authenticated
  using (user_id = auth.uid() or (is_public = true and exists (
    select 1 from public.notes n2
    where n2.id = notes.id and n2.user_id != auth.uid() and n2.is_public = true
  )));

create policy "R3: users can create notes only as themselves"
  on public.notes
  for insert
  to authenticated
  with check (user_id = auth.uid());

create policy "R4: users can edit their own notes only, cannot transfer ownership"
  on public.notes
  for update
  to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "R4: users can delete their own notes only"
  on public.notes
  for delete
  to authenticated
  using (user_id = auth.uid());

create policy "R5: anonymous visitors cannot access any notes"
  on public.notes
  for all
  to anon
  using (false)
  with check (false);

create policy "R6: service role has full access"
  on public.notes
  for all
  to service_role
  using (true)
  with check (true);
