```sql
create schema private;

grant usage on schema private to authenticated;

create function private.is_suspended(p_user_id uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select suspended from public.accounts where user_id = p_user_id), false)
$$;

create function private.file_owner(p_file_id bigint) returns uuid
language sql stable security definer set search_path = ''
as $$
  select f.owner_id from public.files f where f.id = p_file_id
$$;

create function private.has_active_share(p_file_id bigint, p_user_id uuid, p_require_edit boolean) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.file_shares fs
    where fs.file_id = p_file_id
      and fs.shared_with = p_user_id
      and (fs.expires_at is null or fs.expires_at > now())
      and (not p_require_edit or fs.can_edit)
  )
$$;

alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create policy "accounts_select_self"
  on public.accounts
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "files_select_owner"
  on public.files
  for select
  to authenticated
  using (owner_id = auth.uid() or not private.is_suspended(auth.uid()) and private.has_active_share(id, auth.uid(), false));

create policy "files_insert_owner"
  on public.files
  for insert
  to authenticated
  with check (owner_id = auth.uid() and not private.is_suspended(auth.uid()));

create policy "files_update_owner_or_edit_share"
  on public.files
  for update
  to authenticated
  using (owner_id = auth.uid() or (not private.is_suspended(auth.uid()) and private.has_active_share(id, auth.uid(), true)))
  with check (owner_id = auth.uid() or (not private.is_suspended(auth.uid()) and private.has_active_share(id, auth.uid(), true)));

create policy "files_delete_owner"
  on public.files
  for delete
  to authenticated
  using (owner_id = auth.uid() and not private.is_suspended(auth.uid()));

create policy "file_shares_select_owner_or_addressee"
  on public.file_shares
  for select
  to authenticated
  using (
    private.file_owner(file_id) = auth.uid()
    or (shared_with = auth.uid() and not private.is_suspended(auth.uid()))
  );

create policy "file_shares_insert_owner"
  on public.file_shares
  for insert
  to authenticated
  with check (private.file_owner(file_id) = auth.uid() and not private.is_suspended(auth.uid()));

create policy "file_shares_update_owner"
  on public.file_shares
  for update
  to authenticated
  using (private.file_owner(file_id) = auth.uid() and not private.is_suspended(auth.uid()))
  with check (private.file_owner(file_id) = auth.uid() and not private.is_suspended(auth.uid()));

create policy "file_shares_delete_owner"
  on public.file_shares
  for delete
  to authenticated
