    created_by = auth.uid()
    and status in ('draft', 'sent')
    and (
      (customer is null or amount is null or private.can_advance_draft_to_sent(status))
      or (private.is_finance_staff() and status = 'sent' and private.can_set_final_status(status))
    )
  );

