create function private.invite_valid(p_token text) returns table (org_id bigint, role text, expires_at timestamptz, accepted_at timestamptz)
language sql stable security definer set search_path = ''
as $$
  select i.org_id, i.role, i.expires_at, i.accepted_at
  from public.invites i
  where i.token = p_token
$$;

create function public.accept_invite(p_token text) returns bigint
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_row private.invite_valid%rowtype;
  v_email text;
begin
  if v_uid is null then
    raise exception 'accept_invite requires a signed-in user';
  end if;

  select i.org_id, i.role, i.expires_at, i.accepted_at, i.email
  into v_row, v_email
  from public.invites i
  where i.token = p_token;

  if not found then
    raise exception 'unknown invite token';
  end if;

  if v_row.accepted_at is not null then
    raise exception 'invite has already been accepted';
  end if;

  if v_row.expires_at <= now() then
    raise exception 'invite has expired';
  end if;

  select auth.email() into v_email;
  if v_email is null then
    raise exception 'user email is not verified';
  end if;

  if lower(v_email) <> lower(i.email) then
    raise exception 'invite email does not match verified user email';
  end if;

  perform 1 from public.org_members
  where org_id = v_row.org_id and user_id = v_uid;

  insert into public.org_members (org_id, user_id, role)
  values (v_row.org_id, v_uid, v_row.role);

  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_row.org_id;
end
$$;

