language sql
security definer set search_path = public
as $$
  select exists (
    select 1 from public.prescriptions pr
    where pr.id = p_prescription_id
      and pr.expires_at > now()
      and pr.refills_left > 0
      and pr.patient_id != auth.uid()
      and private.is_pharmacist()
  )
$$;

