language plpgsql
security definer set search_path = public
as $$
declare
  v_pharmacist_id uuid;
  v_refills_left integer;
  v_prescription_exists boolean;
begin
  select auth.uid() into v_pharmacist_id;

  if v_pharmacist_id is null then
    raise exception 'Authentication required';
  end if;

  if not private.is_pharmacist() then
    raise exception 'Only pharmacists can dispense prescriptions';
  end if;

  select exists (select 1 from public.prescriptions where id = p_prescription_id) into v_prescription_exists;

