  if v_patient_uuid is null then
    raise exception 'Prescription does not exist';
  end if;

  if v_patient_uuid = v_pharmacist_uuid then
    raise exception 'A pharmacist cannot dispense their own prescription';
  end if;

  if public.prescription_expired(p_prescription_id) then
    raise exception 'Prescription has expired';
  end if;

  select refills_left into v_refills from public.prescriptions where id = p_prescription_id;

  if v_refills <= 0 then
    raise exception 'No refills left';
  end if;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_uuid, now());

  perform public.update_prescription_refills(p_prescription_id, 1);

  return v_refills - 1;
end;
$$;

