returns boolean
language sql
security definer set search_path = public
as $$
  select exists (select 1 from public.prescriptions where id = p_prescription_id);
$$;

create function public.prescription_expired(p_prescription_id bigint)
returns boolean
language sql
security definer set search_path = public
as $$
  select exists (
    select 1 from public.prescriptions
    where id = p_prescription_id
    and expires_at < now()
  );
$$;

create function public.prescription_refills_left(p_prescription_id bigint)
returns integer
language sql
security definer set search_path = public
as $$
  select coalesce((select refills_left from public.prescriptions where id = p_prescription_id), 0);
$$;

create function public.is_own_prescription(p_prescription_id bigint)
returns boolean
language sql
security definer set search_path = public
as $$
  select exists (
    select 1 from public.prescriptions
    where id = p_prescription_id
    and patient_id = auth.uid()
  );
$$;

create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer set search_path = public
as $$
declare
  v_pharmacist_is_caller boolean;
  v_prescription_exists boolean;
  v_expired boolean;
  v_refills integer;
  v_own boolean;
  v_patient_id uuid;
begin
  v_pharmacist_is_caller := public.is_pharmacist();
  v_prescription_exists := public.prescription_exists(p_prescription_id);
  v_expired := public.prescription_expired(p_prescription_id);
  v_refills := public.prescription_refills_left(p_prescription_id);
  v_own := public.is_own_prescription(p_prescription_id);

  if not v_pharmacist_is_caller then
    raise exception 'Only pharmacists can dispense prescriptions';
  end if;

  if not v_prescription_exists then
    raise exception 'Prescription does not exist';
  end if;

  if v_expired then
    raise exception 'Prescription has expired';
  end if;

  if v_refills <= 0 then
    raise exception 'No refills left';
  end if;

  if v_own then
    raise exception 'Cannot dispense your own prescription';
  end if;

  select patient_id into v_patient_id from public.prescriptions where id = p_prescription_id;

  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id
  and refills_left > 0;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  return public.prescription_refills_left(p_prescription_id);
end;
$$;

