create function private.enforce_segment_update()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id <> old.id
     or new.project_id <> old.project_id
     or new.lang <> old.lang
     or new.source_text <> old.source_text then
    raise exception 'segments cannot be moved or have their source text changed';
  end if;

  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be modified';
  end if;

  if new.status = 'reviewed' then
    if not private.can_review(old.project_id, old.lang, old.status) then
      raise exception 'only reviewers can mark a segment as reviewed';
    end if;
  elsif new.status <> 'draft' then
    raise exception 'only draft segments can be edited';
  end if;

  if new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by must be the performing user';
  end if;

  return new;
end;
$$;

