create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
  v_my_sign_order integer;
  v_signed_count integer;
  v_total_recipients integer;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id;
  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status (current status: %)', v_envelope.status;
  end if;

  select sign_order into v_my_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_uid;

  if v_my_sign_order is null then
    raise exception 'Not a recipient of this envelope';
  end if;

  if v_envelope.signed_at is not null then
    raise exception 'Already signed this envelope';
  end if;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  select count(*) into v_total_recipients
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  if v_signed_count >= v_total_recipients then
    raise exception 'All recipients have already signed';
  end if;

  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id != v_uid
      and r.sign_order < v_my_sign_order
      and r.signed_at is null
  ) then
    raise exception 'A previous signer has not yet signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_uid;

  perform 1 from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if found then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id;
  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope.sender_id != v_uid then
    raise exception 'Only the sender can void an envelope';
  end if;

  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status (current status: %)', v_envelope.status;
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

revoke all on function public.sign_envelope(bigint) from public, anon;
revoke all on function public.void_envelope(bigint) from public, anon;

