create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
  v_order integer;
  v_signed_count integer;
  v_total_count integer;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id;
  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status, current status: %', v_envelope.status;
  end if;

  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id and r.user_id = v_uid and r.signed_at is not null
  ) then
    raise exception 'You have already signed this envelope';
  end if;

  select count(*) into v_total_count from public.envelope_recipients where envelope_id = p_envelope_id;
  select count(*) into v_signed_count from public.envelope_recipients where envelope_id = p_envelope_id and signed_at is not null;

  select sign_order into v_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_uid;

  if v_order is null then
    raise exception 'You are not a recipient of this envelope';
  end if;

  if v_signed_count > 0 then
    select exists (
      select 1 from public.envelope_recipients r
      where r.envelope_id = p_envelope_id and r.sign_order < v_order and r.signed_at is null
    ) into exists_before;

    if exists_before then
      raise exception 'Previous signers have not yet signed';
    end if;
  end if;

  perform 1 from public.envelope_recipients
  where envelope_id = p_envelope_id
  and user_id = v_uid
  and signed_at = now();

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
  and user_id = v_uid
  and signed_at is null;

  select count(*) into v_signed_count from public.envelope_recipients where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_count >= v_total_count then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id;
  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status, current status: %', v_envelope.status;
  end if;

  if v_envelope.sender_id != v_uid then
    raise exception 'Only the sender can void this envelope';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

