    and revoked = false
    and valid_until >= current_date
$$;

create function private.enforce_permit_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.plate is distinct from old.plate then
    raise exception 'only plate may be updated';
  end if;

  if new.revoked is distinct from old.revoked then
    raise exception 'revoked cannot be changed';
  end if;

  if new.valid_until is distinct from old.valid_until then
    raise exception 'valid_until cannot be changed';
  end if;

  if old.revoked = true then
    raise exception 'a revoked permit cannot be modified';
  end if;

  if not private.is_resident(new.unit_id) then
    raise exception 'only residents of the unit may update a permit';
  end if;

  return new;
end
$$;

